function cleanData(text, opts){
  opts=opts||{}; var t=String(text||'');
  if(opts.normalizeEol) t=t.replace(/\r\n?/g,'\n');
  if(opts.stripControl) t=t.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g,'');
  var lines=t.split('\n'); var out=[];
  for(var i=0;i<lines.length;i++){
    var L=lines[i];
    if(opts.trimLines) L=L.replace(/^\s+|\s+$/g,'');
    if(opts.collapseSpaces) L=L.replace(/[ \t]+/g,' ');
    out.push(L);
  }
  t=out.join('\n');
  if(opts.dropEmpty) t=t.replace(/\n{2,}/g,'\n').replace(/^\n+|\n+$/g,'');
  return t;
}

var EXPORTS={cleanData:cleanData};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DataCleanForgePure = EXPORTS; }
